    // =========================================================================
    // 11. SMART CROSS-CONTINENT ROUTE PLANNER (BFS 最短跨图寻路)
    // =========================================================================
    function initRoutePlannerSelects() {
      const startSel = document.getElementById('plannerStartSelect');
      const endSel = document.getElementById('plannerEndSelect');
      const optsHtml = ZONES.map(z => `<option value="${z.id}">[${z.continent === 'kalimdor' ? '卡利姆多' : '东部王国'}] ${z.name} (Lv.${z.level})</option>`).join('');
      startSel.innerHTML = optsHtml;
      endSel.innerHTML = optsHtml;
      startSel.value = 'elwynn';
      endSel.value = 'teldrassil';
    }

    function calculateShortestRoute(startId, endId, factionMode) {
      if (startId === endId) {
        state.plannerPath = { zones: [startId], edges: [] };
        renderPlannerResult(startId, endId, []);
        renderPanoramicMap();
        return;
      }

      // Build adjacency list combining BORDER_PASSES + TRANSIT_ROUTES
      const adj = {};
      ZONES.forEach(z => { adj[z.id] = []; });

      BORDER_PASSES.forEach(p => {
        adj[p.from].push({ to: p.to, via: p.name, mode: '陆路路口', coord: p.fromCoord, detail: p.desc });
        adj[p.to].push({ to: p.from, via: p.name, mode: '陆路路口', coord: p.toCoord, detail: p.desc });
      });

      TRANSIT_ROUTES.forEach(r => {
        if (r.fromZone === r.toZone) return;
        if (factionMode === 'alliance' && r.faction === 'horde') return;
        if (factionMode === 'horde' && r.faction === 'alliance') return;

        adj[r.fromZone].push({ to: r.toZone, via: r.name, mode: r.typeName, coord: r.fromTerminal, detail: r.desc });
        adj[r.toZone].push({ to: r.fromZone, via: r.name, mode: r.typeName, coord: r.toTerminal, detail: r.desc });
      });

      // BFS
      const queue = [startId];
      const visited = new Set([startId]);
      const parent = {};

      while (queue.length > 0) {
        const curr = queue.shift();
        if (curr === endId) break;
        for (const edge of (adj[curr] || [])) {
          if (!visited.has(edge.to)) {
            visited.add(edge.to);
            parent[edge.to] = { from: curr, ...edge };
            queue.push(edge.to);
          }
        }
      }

      if (!visited.has(endId)) {
        state.plannerPath = null;
        document.getElementById('plannerResultBox').innerHTML = `
          <div class="text-xs text-rose-300 p-2">未找到符合当前阵营限制的通行路线，请尝试切换为「全航线通用」。</div>
        `;
        renderPanoramicMap();
        return;
      }

      const steps = [];
      const zoneSeq = [endId];
      let curr = endId;
      while (curr !== startId) {
        const step = parent[curr];
        steps.unshift(step);
        zoneSeq.unshift(step.from);
        curr = step.from;
      }

      state.plannerPath = { zones: zoneSeq, edges: steps };
      if (state.viewMode === 'zone') returnToWorldMap();
      renderPanoramicMap();
      renderPlannerResult(startId, endId, steps);
    }

    function renderPlannerResult(startId, endId, steps) {
      const box = document.getElementById('plannerResultBox');
      const sZone = zoneMap[startId];
      const eZone = zoneMap[endId];

      if (steps.length === 0) {
        box.innerHTML = `<div class="text-xs text-emerald-300">起点与终点相同，您已在「${sZone.name}」。</div>`;
        return;
      }

      box.innerHTML = `
        <div class="flex items-center justify-between border-b border-slate-800 pb-2 mb-2">
          <div class="text-xs font-bold text-amber-300">
            ${sZone.name} ➔ ${eZone.name}
          </div>
          <span class="text-[11px] px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 font-semibold">共 ${steps.length} 步跨图</span>
        </div>
        <div class="space-y-2">
          ${steps.map((st, i) => {
            const fZ = zoneMap[st.from];
            const tZ = zoneMap[st.to];
            const isTransit = st.mode !== '陆路路口';
            const badgeCls = isTransit
              ? 'bg-cyan-500/20 text-cyan-300 border-cyan-500/40'
              : 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40';
            return `
              <div class="p-2 rounded-lg bg-[#111c32] border border-slate-800 text-xs">
                <div class="flex items-center justify-between gap-1">
                  <span class="font-bold text-white">${i + 1}. ${fZ.name} ➔ ${tZ.name}</span>
                  <span class="text-[10px] px-1.5 py-0.5 rounded border ${badgeCls}">${st.mode}</span>
                </div>
                <div class="text-amber-300 font-medium mt-1">途径: ${st.via}</div>
                <div class="text-[11px] text-slate-400 font-mono mt-0.5">${st.coord}</div>
              </div>
            `;
          }).join('')}
        </div>
      `;
    }

    // =========================================================================
    // 12. ZONE DIRECTORY & SEARCH (区域名录与搜索栏)
    // =========================================================================
    function renderDirectoryList() {
      const container = document.getElementById('directoryListContainer');
      const filterVal = document.getElementById('directoryFactionFilter').value;
      container.innerHTML = '';

      const list = ZONES.filter(z => filterVal === 'all' || z.faction === filterVal);
      list.forEach(z => {
        const fBadge = getFactionBadgeInfo(z.faction);
        const item = document.createElement('div');
        item.className = 'p-2 rounded-lg bg-[#0b1323] hover:bg-[#152340] border border-slate-800 hover:border-amber-500/40 flex items-center justify-between cursor-pointer transition-all';
        item.innerHTML = `
          <div>
            <div class="text-xs font-bold text-amber-200">${z.name} <span class="text-[11px] text-slate-400 font-normal">${z.enName}</span></div>
            <div class="text-[11px] text-slate-400 mt-0.5">${z.continent === 'kalimdor' ? '卡利姆多' : '东部王国'} · Lv.${z.level}</div>
          </div>
          <div class="flex items-center gap-1.5">
            <span class="text-[10px] px-1.5 py-0.5 rounded ${fBadge.cls}">${fBadge.text.slice(0,2)}</span>
            <span class="text-xs text-amber-400 font-bold">进入 ➔</span>
          </div>
        `;
        item.addEventListener('click', () => openZoneDetail(z.id));
        container.appendChild(item);
      });
    }

    function setupSearch() {
      const input = document.getElementById('zoneSearchInput');
      const clearBtn = document.getElementById('clearSearchBtn');
      const dropdown = document.getElementById('searchDropdown');

      input.addEventListener('input', () => {
        const q = input.value.trim().toLowerCase();
        if (!q) {
          clearBtn.classList.add('hidden');
          dropdown.classList.add('hidden');
          return;
        }
        clearBtn.classList.remove('hidden');

        const matchedZones = ZONES.filter(z =>
          z.name.toLowerCase().includes(q) ||
          z.enName.toLowerCase().includes(q) ||
          (z.capital && z.capital.toLowerCase().includes(q)) ||
          (z.pois && z.pois.some(p => p.name.toLowerCase().includes(q)))
        );
        const matchedPasses = BORDER_PASSES.filter(p => p.name.toLowerCase().includes(q));
        const matchedTransits = TRANSIT_ROUTES.filter(r => r.name.toLowerCase().includes(q));

        dropdown.innerHTML = '';
        if (matchedZones.length === 0 && matchedPasses.length === 0 && matchedTransits.length === 0) {
          dropdown.innerHTML = `<div class="p-3 text-xs text-slate-400 text-center">未找到匹配的地图区域、路口或航线</div>`;
        } else {
          matchedZones.slice(0, 6).forEach(z => {
            const row = document.createElement('div');
            row.className = 'p-2.5 hover:bg-slate-800 cursor-pointer text-xs flex items-center justify-between';
            row.innerHTML = `
              <div>
                <span class="font-bold text-amber-300">🗺️ ${z.name}</span>
                <span class="text-slate-400 ml-1">(Lv.${z.level})</span>
              </div>
              <span class="text-[11px] text-emerald-300">点击进入区域</span>
            `;
            row.addEventListener('click', () => {
              dropdown.classList.add('hidden');
              openZoneDetail(z.id);
            });
            dropdown.appendChild(row);
          });

          matchedPasses.slice(0, 4).forEach(p => {
            const row = document.createElement('div');
            row.className = 'p-2.5 hover:bg-slate-800 cursor-pointer text-xs flex items-center justify-between';
            row.innerHTML = `
              <span class="font-semibold text-emerald-300">🧭 路口: ${p.name}</span>
              <span class="text-[11px] text-slate-400">定位路口</span>
            `;
            row.addEventListener('click', () => {
              dropdown.classList.add('hidden');
              if (state.viewMode === 'zone') returnToWorldMap();
              selectPassWaypoint(p.id);
            });
            dropdown.appendChild(row);
          });

          matchedTransits.slice(0, 4).forEach(r => {
            const row = document.createElement('div');
            row.className = 'p-2.5 hover:bg-slate-800 cursor-pointer text-xs flex items-center justify-between';
            // 图标与配色随航线类型变化，避免飞艇/地铁被统一标成船只
            const icon = r.type === 'zeppelin' ? '🎈' : r.type === 'tram' ? '🚇' : '🚢';
            const color = r.type === 'zeppelin' ? 'text-rose-300' : r.type === 'tram' ? 'text-violet-300' : 'text-cyan-300';
            row.innerHTML = `
              <span class="font-semibold ${color}">${icon} 航线: ${r.name}</span>
              <span class="text-[11px] text-slate-400">高亮虚线</span>
            `;
            row.addEventListener('click', () => {
              dropdown.classList.add('hidden');
              if (state.viewMode === 'zone') returnToWorldMap();
              selectTransitRoute(r.id);
            });
            dropdown.appendChild(row);
          });
        }
        dropdown.classList.remove('hidden');
      });

      clearBtn.addEventListener('click', () => {
        input.value = '';
        clearBtn.classList.add('hidden');
        dropdown.classList.add('hidden');
      });

      document.addEventListener('click', (e) => {
        if (!input.contains(e.target) && !dropdown.contains(e.target)) {
          dropdown.classList.add('hidden');
        }
      });
    }

    // =========================================================================
    // 12b. 部落练级副本任务清单渲染（右侧栏「副本任务」页签）
    // =========================================================================
    const DUNGEON_SHARE_BADGE = {
      yes: { cls: 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40', label: '可共享' },
      no: { cls: 'bg-rose-500/20 text-rose-300 border-rose-500/40', label: '不可共享' },
      partial: { cls: 'bg-amber-500/20 text-amber-300 border-amber-500/40', label: '共享复杂' }
    };

    function renderDungeonQuestList() {
      const box = document.getElementById('dungeonQuestList');
      if (!box) return;
      const searchEl = document.getElementById('dungeonQuestSearch');
      const shareEl = document.getElementById('dungeonShareFilter');
      const q = (searchEl ? searchEl.value : '').trim().toLowerCase();
      const share = shareEl ? shareEl.value : 'all';

      const hit = (txt) => String(txt || '').toLowerCase().includes(q);
      // 任务级命中：任务名 / 接任务 NPC / 任务备注
      const matchQuest = (x) => hit(x.n) || hit(x.g) || hit(x.note);
      // 副本级命中：副本名 / 英文名 / 副本备注 —— 命中则视为「整本命中」，展示该副本全部任务
      const matchDungeon = (d) => !q || hit(d.name) || hit(d.en) || (d.notes || []).some(hit);
      // 共享性筛选（独立于关键词筛选）
      const shareOk = (x) => {
        if (share === 'yes' && x.s !== 'yes') return false;
        if (share === 'no' && x.s !== 'no') return false;
        if (share === 'partial' && x.s !== 'partial') return false;
        return true;
      };

      // 副本名/备注命中，或副本内存在命中的任务，才保留该副本
      const list = DUNGEON_QUESTS.filter(d => matchDungeon(d) || d.quests.some(matchQuest));
      let shownDungeons = 0, shownQuests = 0, sharedQuests = 0;
      const html = [];

      list.forEach(d => {
        // 副本整体命中 -> 全部任务（仅受共享性筛选约束）；否则只保留命中的任务
        const quests = d.quests.filter(x => shareOk(x) && (matchDungeon(d) || matchQuest(x)));
        const hasNotes = (d.notes || []).length > 0;
        // 既无可见任务又无备注 -> 该副本在当前筛选下没有内容，直接隐藏
        if (!quests.length && !hasNotes) return;
        shownDungeons++;

        // 关联区域按钮（点击跳到该区详图）
        const zoneBtns = (d.zones || []).map(zid => {
          const z = zoneMap[zid];
          if (!z) return '';
          return `<button data-dungeon-zone="${zid}" class="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/15 text-emerald-300 border border-emerald-500/30 hover:bg-emerald-500/30 transition-all">🗺️ ${z.name}</button>`;
        }).join('');

        const notesHtml = (d.notes || []).map(n =>
          `<div class="text-[11px] text-amber-200/80 leading-relaxed">📌 ${n}</div>`).join('');

        const questHtml = quests.map(x => {
          shownQuests++;
          if (x.s === 'yes') sharedQuests++;
          const badge = DUNGEON_SHARE_BADGE[x.s] || DUNGEON_SHARE_BADGE.partial;
          const dot = x.s === 'yes' ? '#34d399' : (x.s === 'no' ? '#fb7185' : '#fbbf24');
          const scope = x.scope ? `<span class="text-[10px] px-1 rounded bg-slate-700/60 text-slate-300">${x.scope}</span>` : '';
          const lv = (x.lv !== undefined) ? `<span class="text-[10px] px-1 rounded bg-slate-700/60 text-slate-300 font-mono">Lv.${x.lv}</span>` : '';
          const note = x.note ? `<div class="text-[11px] text-rose-300/85 mt-0.5">⚠ ${x.note}</div>` : '';
          return `
            <div class="px-2 py-1.5 rounded bg-[#0b1323] border border-slate-800">
              <div class="flex items-center gap-1.5 flex-wrap">
                <span class="w-1.5 h-1.5 rounded-full shrink-0" style="background:${dot}"></span>
                <span class="text-xs font-bold text-amber-200">${x.n}</span>
                ${lv}${scope}
                <span class="text-[10px] px-1 rounded border ${badge.cls}">${badge.label}</span>
              </div>
              <div class="text-[11px] text-slate-400 mt-0.5">📍 ${x.g || '—'}</div>
              ${note}
            </div>`;
        }).join('');

        html.push(`
          <div class="rounded-lg border border-amber-500/20 bg-[#0a111f] overflow-hidden">
            <div class="px-2.5 py-2 bg-[#141f36] border-b border-slate-800 flex items-center gap-2">
              <span class="text-base leading-none">${d.emoji}</span>
              <div class="flex-1 min-w-0">
                <div class="text-xs font-bold text-amber-300">${d.name}</div>
                <div class="text-[10px] text-slate-500 truncate">${d.en}</div>
              </div>
              ${d.new ? '<span class="text-[10px] px-1 py-0.5 rounded bg-cyan-500/15 text-cyan-300 border border-cyan-500/30 shrink-0">《无限》新增</span>' : ''}
              <span class="text-[10px] px-1.5 py-0.5 rounded bg-amber-500/15 text-amber-300 border border-amber-500/30 font-mono shrink-0">Lv.${d.level}</span>
            </div>
            <div class="p-2 space-y-1.5">
              ${zoneBtns ? `<div class="flex flex-wrap gap-1">${zoneBtns}</div>` : ''}
              ${notesHtml ? `<div class="space-y-0.5">${notesHtml}</div>` : ''}
              ${questHtml}
            </div>
          </div>`);
      });

      const totalQuests = DUNGEON_QUESTS.reduce((a, d) => a + d.quests.length, 0);
      const totalShared = DUNGEON_QUESTS.reduce((a, d) => a + d.quests.filter(x => x.s === 'yes').length, 0);

      box.innerHTML = `
        <div class="text-[11px] text-slate-400 px-0.5">
          共 ${DUNGEON_QUESTS.length} 个副本 · ${totalQuests} 个任务 · 其中 ${totalShared} 个可直接共享
          ${shownDungeons !== DUNGEON_QUESTS.length || shownQuests !== totalQuests
            ? `<span class="text-amber-300">（当前筛选：${shownDungeons} 个副本 / ${shownQuests} 个任务）</span>` : ''}
        </div>
        ${html.length ? html.join('') : '<div class="text-xs text-slate-400 text-center py-8">没有符合条件的副本任务</div>'}
      `;

      // 关联区域 -> 跳到该区详图
      box.querySelectorAll('[data-dungeon-zone]').forEach(btn => {
        btn.addEventListener('click', () => {
          switchSideTab('inspector');
          openZoneDetail(btn.dataset.dungeonZone);
        });
      });
    }

    // =========================================================================
    // 13. SIDEBAR TABS, PAN/ZOOM & GLOBAL CONTROLS
    // =========================================================================
    function switchSideTab(tabName) {
      document.querySelectorAll('.side-tab-btn').forEach(btn => {
        const active = btn.dataset.sideTab === tabName;
        btn.className = active
          ? 'side-tab-btn py-2 px-2 rounded-lg text-xs font-bold bg-amber-500 text-slate-950 shadow transition-all'
          : 'side-tab-btn py-2 px-2 rounded-lg text-xs font-bold text-slate-300 hover:text-amber-300 transition-all';
      });
      document.getElementById('sideTabInspector').classList.toggle('hidden', tabName !== 'inspector');
      document.getElementById('sideTabPlanner').classList.toggle('hidden', tabName !== 'planner');
      document.getElementById('sideTabDirectory').classList.toggle('hidden', tabName !== 'directory');
      document.getElementById('sideTabDungeons').classList.toggle('hidden', tabName !== 'dungeons');
      if (tabName === 'dungeons') renderDungeonQuestList();
    }

    function applyMapTransform() {
      const svg = document.getElementById('worldMapSvg');
      svg.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
    }

    function setupInteractions() {
      // Back to World Map buttons + ESC key
      document.getElementById('backToWorldBtn').addEventListener('click', returnToWorldMap);
      document.getElementById('detailBackBtn').addEventListener('click', returnToWorldMap);
      document.getElementById('brandLogoBtn').addEventListener('click', returnToWorldMap);
      window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && state.viewMode === 'zone') {
          returnToWorldMap();
        }
      });

      // Continent Tabs
      document.querySelectorAll('.continent-tab').forEach(btn => {
        btn.addEventListener('click', () => {
          state.continentFilter = btn.dataset.continent;
          document.querySelectorAll('.continent-tab').forEach(b => {
            const active = b.dataset.continent === state.continentFilter;
            b.className = active
              ? 'continent-tab px-2.5 py-1 rounded-md text-xs font-semibold bg-amber-500/20 text-amber-300 border border-amber-500/40 transition-all'
              : 'continent-tab px-2.5 py-1 rounded-md text-xs font-semibold text-slate-300 hover:text-amber-200 transition-all';
          });
          if (state.viewMode === 'zone') returnToWorldMap();
          // Adjust camera focus for continent
          if (state.continentFilter === 'kalimdor') {
            state.zoom = 1.35; state.panX = 240; state.panY = 0;
          } else if (state.continentFilter === 'ek') {
            state.zoom = 1.35; state.panX = -260; state.panY = 0;
          } else {
            state.zoom = 1; state.panX = 0; state.panY = 0;
          }
          applyMapTransform();
          renderPanoramicMap();
        });
      });

      // Layer Toggles
      document.querySelectorAll('.layer-toggle').forEach(btn => {
        btn.addEventListener('click', () => {
          const layerKey = btn.dataset.layer;
          state.layers[layerKey] = !state.layers[layerKey];
          btn.classList.toggle('opacity-40', !state.layers[layerKey]);
          renderPanoramicMap();
        });
      });

      // Zoom & Pan on Panoramic Map
      const wrapper = document.getElementById('worldMapWrapper');
      document.getElementById('zoomInBtn').addEventListener('click', () => {
        state.zoom = Math.min(2.6, +(state.zoom + 0.25).toFixed(2));
        applyMapTransform();
      });
      document.getElementById('zoomOutBtn').addEventListener('click', () => {
        state.zoom = Math.max(0.8, +(state.zoom - 0.25).toFixed(2));
        applyMapTransform();
      });
      document.getElementById('zoomResetBtn').addEventListener('click', () => {
        state.zoom = 1; state.panX = 0; state.panY = 0;
        applyMapTransform();
      });

      wrapper.addEventListener('wheel', (e) => {
        e.preventDefault();
        const delta = e.deltaY < 0 ? 0.15 : -0.15;
        state.zoom = Math.max(0.85, Math.min(2.8, +(state.zoom + delta).toFixed(2)));
        applyMapTransform();
      }, { passive: false });

      wrapper.addEventListener('mousedown', (e) => {
        if (e.target.closest('.zone-poly') || e.target.closest('circle') || e.target.closest('path')) return;
        state.isDragging = true;
        state.dragStartX = e.clientX - state.panX;
        state.dragStartY = e.clientY - state.panY;
      });
      window.addEventListener('mousemove', (e) => {
        if (!state.isDragging) return;
        state.panX = e.clientX - state.dragStartX;
        state.panY = e.clientY - state.dragStartY;
        applyMapTransform();
      });
      window.addEventListener('mouseup', () => {
        state.isDragging = false;
      });

      // Live Coordinate Readout on World Map
      const worldSvg = document.getElementById('worldMapSvg');
      worldSvg.addEventListener('mousemove', (e) => {
        const rect = worldSvg.getBoundingClientRect();
        const x = Math.max(0, Math.min(100, ((e.clientX - rect.left) / rect.width) * 100)).toFixed(1);
        const y = Math.max(0, Math.min(100, ((e.clientY - rect.top) / rect.height) * 100)).toFixed(1);
        document.getElementById('coordTracker').textContent = `全景坐标: ${x}, ${y}`;
      });

      // Sidebar Tabs
      document.querySelectorAll('.side-tab-btn').forEach(btn => {
        btn.addEventListener('click', () => switchSideTab(btn.dataset.sideTab));
      });

      // Transit Filter Buttons
      document.querySelectorAll('.transit-filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          state.transitCardFilter = btn.dataset.transitFilter;
          document.querySelectorAll('.transit-filter-btn').forEach(b => {
            const active = b.dataset.transitFilter === state.transitCardFilter;
            b.className = active
              ? 'transit-filter-btn px-2.5 py-1 rounded text-xs font-semibold bg-amber-500/20 text-amber-300 border border-amber-500/40'
              : 'transit-filter-btn px-2.5 py-1 rounded text-xs font-semibold text-slate-300 hover:bg-slate-800';
          });
          renderTransitCardsGrid();
        });
      });

      // Route Planner Controls
      document.querySelectorAll('.planner-faction-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          state.plannerFaction = btn.dataset.plannerFaction;
          document.querySelectorAll('.planner-faction-btn').forEach(b => {
            const active = b.dataset.plannerFaction === state.plannerFaction;
            b.className = active
              ? 'planner-faction-btn py-1.5 rounded text-xs font-semibold bg-amber-500/20 text-amber-300 border border-amber-500/50'
              : 'planner-faction-btn py-1.5 rounded text-xs font-semibold bg-slate-800 text-slate-300 border border-slate-700';
          });
        });
      });

      document.getElementById('swapPlannerBtn').addEventListener('click', () => {
        const s = document.getElementById('plannerStartSelect');
        const e = document.getElementById('plannerEndSelect');
        const tmp = s.value;
        s.value = e.value;
        e.value = tmp;
      });

      document.getElementById('runPlannerBtn').addEventListener('click', () => {
        const s = document.getElementById('plannerStartSelect').value;
        const e = document.getElementById('plannerEndSelect').value;
        calculateShortestRoute(s, e, state.plannerFaction);
      });

      document.getElementById('clearPlannerBtn').addEventListener('click', () => {
        state.plannerPath = null;
        document.getElementById('plannerResultBox').innerHTML = `<div class="text-xs text-slate-400">已清除全景地图上的路线高亮。请选择起点与终点重新计算。</div>`;
        renderPanoramicMap();
      });

      document.querySelectorAll('.preset-route-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const [s, e, f] = btn.dataset.presetRoute.split(',');
          document.getElementById('plannerStartSelect').value = s;
          document.getElementById('plannerEndSelect').value = e;
          state.plannerFaction = f;
          calculateShortestRoute(s, e, f);
        });
      });

      document.getElementById('directoryFactionFilter').addEventListener('change', renderDirectoryList);

      // 副本任务清单：搜索 + 共享性筛选
      const dqSearch = document.getElementById('dungeonQuestSearch');
      const dqShare = document.getElementById('dungeonShareFilter');
      if (dqSearch) dqSearch.addEventListener('input', renderDungeonQuestList);
      if (dqShare) dqShare.addEventListener('change', renderDungeonQuestList);
      document.getElementById('breadcrumbSub').textContent = buildAtlasSummary();
      const expBtn = document.getElementById('exportAtlasDataBtn');
      if (expBtn) {
        expBtn.addEventListener('click', () => {
          const payload = {
            version: '3.0-Full-Infinite-Atlas',
            zoneCount: ZONES.length,
            borderPassCount: BORDER_PASSES.length,
            transitRouteCount: TRANSIT_ROUTES.length,
            zones: ZONES,
            borderPasses: BORDER_PASSES,
            transitRoutes: TRANSIT_ROUTES
          };
          const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json;charset=utf-8' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = 'wow_infinite_atlas_full_data.json';
          document.body.appendChild(a);
          a.click();
          a.remove();
          URL.revokeObjectURL(url);
        });
      }
    }

    // =========================================================================
    // 14. INITIALIZE ON LOAD
    // =========================================================================
    // 底图位置/尺寸、大洲标题、无尽之海与大漩涡全部由 MAP_LAYOUT 推导，
    // 不在 HTML 里写死坐标，避免素材重算后界面与数据脱节。
    function applyMapLayout() {
      const kal = MAP_LAYOUT.continents['1414'];
      const ek = MAP_LAYOUT.continents['1415'];
      const setImg = (id, c) => {
        const el = document.getElementById(id);
        if (!el || !c) return;
        el.setAttribute('href', c.img);
        el.setAttribute('x', c.x);
        el.setAttribute('y', c.y);
        el.setAttribute('width', c.w);
        el.setAttribute('height', c.h);
      };
      setImg('baseMapKalimdor', kal);
      setImg('baseMapEK', ek);

      const kalCx = kal ? kal.x + kal.w / 2 : 0;
      const ekCx = ek ? ek.x + ek.w / 2 : 0;
      const seaCx = kal && ek ? (kal.x + kal.w + ek.x) / 2 : 0;
      const setX = (id, v) => {
        const el = document.getElementById(id);
        if (el) el.setAttribute('x', v);
      };
      setX('kalimdorTitle', kalCx);
      setX('ekTitle', ekCx);
      setX('seaLabel', seaCx);

      const mg = document.getElementById('maelstromGroup');
      if (mg && kal && ek) {
        const cy = (kal.y + kal.h / 2 + ek.y + ek.h / 2) / 2;
        mg.setAttribute('transform', `translate(${seaCx}, ${cy.toFixed(1)})`);
      }
    }

    window.addEventListener('DOMContentLoaded', () => {
      applyMapLayout();
      initRoutePlannerSelects();
      syncDynamicCounts();
      setupSearch();
      setupInteractions();
      renderPanoramicMap();
      renderInspectorPanel();
      renderTransitCardsGrid();
      renderDirectoryList();
      renderDungeonQuestList();
      // Default demo route in planner box
      document.getElementById('plannerResultBox').innerHTML = `
        <div class="text-xs text-slate-400 leading-relaxed">
          👆 选择任意两张地图并点击「开始计算最佳路线」，系统将自动结合<span class="text-emerald-300">陆路路口</span>、<span class="text-rose-300">部落飞艇</span>、<span class="text-cyan-300">联盟/中立船只</span>与<span class="text-violet-300">矿道地铁</span>为您规划跨图方案。
        </div>
      `;
    });
